  const dv = new DataView(shBytes);
  const magic = dv.getUint32(0, false);
  const mono = magic === 0x5348514d; // "SHQM"
  if (!mono && magic !== 0x53485131) return false; // "SHQ1"
  if (dv.getUint32(4, true) !== count) return false;
