    const sx = Math.exp(scalesCodebook[Math.round(sc[p])]);
    const sy = Math.exp(scalesCodebook[Math.round(sc[p + 1])]);
    const sz = Math.exp(scalesCodebook[Math.round(sc[p + 2])]);
